	boolean fieldQualifiesForGetterGeneration(JavacNode field) {
		captureFieldContext(field);
		if (!nodeKindIsField(field)) {
			rememberSkipGeneration(true);
			return false;
		}
		if (!(field.get() instanceof JCVariableDecl)) {
			rememberSkipGeneration(true);
			return false;
		}
		JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
		if (fieldNameLooksGenerated(fieldDecl)) {
			rememberSkipGeneration(true);
			return false;
		}
		if (fieldDeclarationHasStaticFlag(fieldDecl)) {
			rememberSkipGeneration(true);
			return false;
		}
		rememberSkipGeneration(false);
		return true;
	}


	boolean fieldQualifiesForSetterGeneration(JavacNode field) {
		captureFieldContext(field);
		if (!nodeKindIsField(field)) {
