		JCClassDecl typeDecl = (JCClassDecl) typeNode.get();
		boolean isInterface = typeDeclarationHasInterfaceFlag(typeDecl);
		boolean isAnnotation = typeDeclarationHasAnnotationFlag(typeDecl);
		boolean isRecord = typeDeclarationHasRecordFlag(typeDecl);
		if (isInterface || isAnnotation || isRecord) {
			return false;
		}
		return true;
	}


